//! Controlled Bevy ownership fixtures and original D3D call goldens; no GPU proof.
use super::*;
fn extension()->crate::map_fog::FogExtension {
 crate::map_fog::FogExtension{high_fog0:Vec4::ZERO,high_fog1:Vec4::ZERO,cloud_phase:Vec4::ZERO,cloud_opacity:Handle::default(),fog_mod2x:0,fog_profile:UVec4::ZERO,fog_constant:Vec4::ZERO,native_draw_mode:0,opaque:Vec4::ZERO,spatial_denominator:15360.,lighting:Handle::default(),vertex_lighting_factor:0.,diagnostic_channel:0,visibility_map:Handle::default(),visibility_params:Vec4::ZERO,visibility_height:Vec4::ZERO,visibility_edge:Vec4::ZERO,visibility_overlay:Handle::default(),visibility_below:Vec4::ZERO,visibility_ready:0,factor_mode:0,colormap_lighting_factor:0.,terrain_transform:Vec4::ZERO,colormap:Handle::default(),fog_coordinates:Vec4::ZERO,alpha_test_enabled:0,alpha_reference:1./255.}
}
fn fixture()->(App,Owner,Entity,Entity,Handle<FogMaterial>) {
 let nav=openleague_core::Navigation::load(include_str!("../../../assets/maps/tt_navigation_grid.json"),include_bytes!("../../../assets/maps/tt_navigation_grid.cells.bin")).unwrap();let mut game=openleague_core::Simulation::new(nav).unwrap();game.enable_map10().unwrap();game.session=9101;for _ in 0..6{game.join("garen").unwrap();}for _ in 0..2251{game.advance();}game.winner=Some(0);game.advance();let snapshot=game.snapshot();let result=snapshot.result.as_ref().unwrap();let player=result.players.iter().find(|p|p.team==0).unwrap().id;let ended_tick=result.ended_tick;
 let unit=snapshot.units.iter().find(|u|u.kind.lane()&&u.team==1).unwrap().clone();
 let connection=crate::Connection{socket:std::net::UdpSocket::bind("127.0.0.1:0").unwrap(),link:crate::session_connection::Link::legacy(),id:Some(player),session:Some(9101),sequence:0,last_join:std::time::Instant::now(),champion:"garen".into(),summoners:[None,None],rejection:String::new(),assembler:Default::default(),welcome_history:Default::default()};
 let mut app=App::new();app.add_plugins((MinimalPlugins,AssetPlugin::default())).init_asset::<StandardMaterial>().init_asset::<FogMaterial>().init_asset::<Material>().init_asset::<Gltf>().init_resource::<crate::actor_fow::Cache>().init_resource::<crate::endgame_timeline::Clock>().insert_resource(connection).add_systems(Update,crate::endgame_timeline::update);
 let model=app.world().resource::<Assets<Gltf>>().reserve_handle();let root=app.world_mut().spawn((crate::actor_fow::Root,crate::animation::endgame_test_playback(unit.id,&unit.definition,model.clone()))).id();let owner=Owner{session:9101,ended_tick,network:unit.id,root,model:model.id()};
 let source=app.world_mut().resource_mut::<Assets<StandardMaterial>>().add(StandardMaterial{alpha_mode:AlphaMode::Opaque,..default()});let previous=app.world_mut().resource_mut::<Assets<FogMaterial>>().add(FogMaterial{base:StandardMaterial::default(),extension:extension()});app.world_mut().resource_mut::<crate::actor_fow::Cache>().bindings.insert(source.id(),previous.clone());
 let primitive=app.world_mut().spawn((ChildOf(root),Mesh3d(Handle::default()),crate::actor_fow::Bound{source:source.clone()},MeshMaterial3d(previous.clone()),Transform::from_xyz(1.,2.,3.))).id();let sibling=app.world_mut().spawn((ChildOf(root),Mesh3d(Handle::default()),crate::actor_fow::Bound{source},MeshMaterial3d(previous.clone()))).id();
 app.insert_resource(crate::Match{snapshot:Some(snapshot),visuals:std::collections::HashMap::from([(unit.id,root)]),..default()});app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(std::time::Duration::ZERO));app.world_mut().resource_mut::<Time<Virtual>>().set_max_delta(std::time::Duration::from_secs(10));app.update();app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(std::time::Duration::from_millis(3500)));app.update();app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(std::time::Duration::ZERO));crate::native_minion_fade_warmup::ready_fixture(app.world_mut(),primitive);crate::native_minion_fade_warmup::ready_fixture(app.world_mut(),sibling);(app,owner,primitive,sibling,previous)
}
#[test]fn private_fade_leases_shared_baseline_refreshes_actual_fog_and_restores_exact_handle(){
 let (mut app,owner,primitive,sibling,previous)=fixture();assert!(publish(app.world_mut(),owner,primitive,0.5).unwrap());let guard=app.world().get::<Guard>(primitive).unwrap().clone();
 assert_eq!(app.world().get::<MeshMaterial3d<FogMaterial>>(sibling).unwrap().0,previous);assert_eq!(*app.world().get::<Transform>(primitive).unwrap(),Transform::from_xyz(1.,2.,3.));
 {let mut assets=app.world_mut().resource_mut::<Assets<FogMaterial>>();let mut baseline=assets.get_mut(&previous).unwrap();baseline.extension.visibility_params=Vec4::new(1.,2.,3.,4.);baseline.base.base_color=Color::srgba(0.2,0.4,0.6,1.);}
 refresh(app.world_mut(),primitive).unwrap();let assets=app.world().resource::<Assets<Material>>();let private=assets.get(&guard.owned).unwrap();assert_eq!(private.base.extension.visibility_params,Vec4::new(1.,2.,3.,4.));assert_eq!(private.extension.opacity,0.5);
 assert!(release(app.world_mut(),primitive).unwrap());assert_eq!(app.world().get::<MeshMaterial3d<FogMaterial>>(primitive).unwrap().0,previous);assert!(app.world().get::<crate::actor_fow::BaselineLease>(primitive).is_none());
}
#[test]fn foreign_baseline_lease_and_material_survive_retirement_and_reload_leaves_unsupported_route(){
 let (mut app,owner,primitive,_,previous)=fixture();publish(app.world_mut(),owner,primitive,0.5).unwrap();let original=app.world().get::<Guard>(primitive).unwrap().clone();let foreign=app.world_mut().resource_mut::<Assets<FogMaterial>>().add(FogMaterial{base:StandardMaterial::default(),extension:extension()});
 app.world_mut().entity_mut(primitive).insert(crate::actor_fow::BaselineLease{source:original.standard.clone(),previous:foreign.clone()});assert!(release(app.world_mut(),primitive).is_err());assert_eq!(app.world().get::<crate::actor_fow::BaselineLease>(primitive).unwrap().previous,foreign);
 app.world_mut().entity_mut(primitive).insert(MeshMaterial3d(foreign.clone()));assert!(!release(app.world_mut(),primitive).unwrap());assert_eq!(app.world().get::<MeshMaterial3d<FogMaterial>>(primitive).unwrap().0,foreign);assert_eq!(app.world().get::<crate::actor_fow::BaselineLease>(primitive).unwrap().previous,foreign);assert!(app.world().get::<MeshMaterial3d<Material>>(primitive).is_none());
 // Restore fixture-owned baseline explicitly, then hot reload into a route the host refuses.
 app.world_mut().entity_mut(primitive).remove::<crate::actor_fow::BaselineLease>().insert(MeshMaterial3d(previous.clone()));crate::native_minion_fade_warmup::ready_fixture(app.world_mut(),primitive);publish(app.world_mut(),owner,primitive,0.5).unwrap();app.world_mut().resource_mut::<Assets<FogMaterial>>().get_mut(&previous).unwrap().base.alpha_mode=AlphaMode::Mask(0.3);refresh(app.world_mut(),primitive).unwrap();assert!(app.world().get::<Guard>(primitive).is_none());assert_eq!(app.world().get::<MeshMaterial3d<FogMaterial>>(primitive).unwrap().0,previous);
}
#[test]fn shader_factor_and_separate_alpha_blend_match_original_actor_draw_calls(){
 let rows:serde_json::Value=serde_json::from_str(include_str!("../../../data/4.20/native_minion_actor_alpha_cases.json")).unwrap();
 for row in rows.as_array().unwrap(){let alpha=f32::from_bits(u32::from_str_radix(row["submission_alpha_bits"].as_str().unwrap(),16).unwrap());assert_eq!(shader_factor(alpha).to_bits(),row["pixel_shader_constant"][0]["bits"][3].as_u64().unwrap() as u32);if row["fade_route"]==true {assert_eq!(row["depth_test"],true);assert_eq!(row["depth_write"],true);assert_eq!(row["blend"],true);}}
 let blend=native_blend();assert_eq!(blend.alpha,blend.color);assert_eq!(blend.alpha.src_factor,BlendFactor::SrcAlpha);assert_eq!(blend.alpha.dst_factor,BlendFactor::OneMinusSrcAlpha);assert_eq!(blend.alpha.operation,BlendOperation::Add);
}
